from langsmith import traceable, uuid7


class FakeOpenAI:
    """Hace de OpenAI: contesta según lo que ve en el historial, sin red."""
    def create(self, model, messages):
        texto = " ".join(m["content"] for m in messages if m["role"] == "user")
        if "What's my name" in messages[-1]["content"]:
            respuesta = "Your name is Sally." if "Sally" in texto else "I don't know your name."
        else:
            respuesta = "Nice to meet you!"
        print(f"  el modelo recibe {len(messages)} mensajes")
        return {"role": "assistant", "content": respuesta}


client = FakeOpenAI()
THREAD_ID = str(uuid7())

# Conversation history store (use a database in production)
thread_store: dict[str, list] = {}

def get_thread_history(thread_id: str) -> list:
    return thread_store.get(thread_id, [])

def save_thread_history(thread_id: str, messages: list):
    thread_store[thread_id] = messages

@traceable(name="Name Agent", metadata={"thread_id": THREAD_ID})
def chat_pipeline(messages: list):
    history_messages = get_thread_history(THREAD_ID)
    all_messages = history_messages + messages
    response_message = client.create(model="gpt-5-nano", messages=all_messages)
    full_conversation = all_messages + [response_message]
    save_thread_history(THREAD_ID, full_conversation)
    return {"messages": full_conversation}

r = chat_pipeline([{"content": "Hi, my name is Sally", "role": "user"}])
print(r["messages"][-1]["content"])
