def etiqueta(valor):
    print("decorando con:", valor)
    def decorador(func):
        def envoltura():
            return f"{func()} [etiqueta={valor}]"
        return envoltura
    return decorador

thread_id = "A"

@etiqueta(thread_id)          # se evalúa AQUÍ, una sola vez
def responder():
    return f"memoria del thread {thread_id}"

